332	// semanticCellPage is one cell's successful response plus the classification
333	// bit the merge keys on.
334	type semanticCellPage struct {
335		body     *search.Response
336		hasUpper bool // any non-repo tier-0/1 row
337	}
338	
339	// classifySemanticCells splits per-cell outcomes into successful pages, hard
340	// failures, and quietly-skipped cells. A cell is skipped — not failed — when
341	// it can't serve the search yet: its gateway has no query-serve route, or the
342	// cluster catalog doesn't expose the placement's jurisdiction at all (a cell
343	// mid-onboarding). Neither is worth warning the user about on every search.
344	func classifySemanticCells(ctx context.Context, results []cellCallResult[*search.Response]) (pages []semanticCellPage, failed []failedCell, lastErr error) {
345		var skipped []string
346		for _, r := range results {
347			switch {
348			case errors.Is(r.err, search.ErrCellUnavailable), errors.Is(r.err, auth.ErrNoCellForJurisdiction):
349				skipped = append(skipped, r.group.label())
350			case r.err != nil:
351				lastErr = r.err
352				failed = append(failed, failedCell{label: r.group.label(), reason: summarizeCellError(r.err)})
353			case r.value != nil:
354				p := semanticCellPage{body: r.value}
355				for _, res := range r.value.Results {
356					// Repo rows never count as an upper tier — they're always
357					// merged regardless of the cell's checkpoint/commit tiers.
358					if res.Type != search.TypeRepo && (tierOf(res) == 0 || tierOf(res) == 1) {
359						p.hasUpper = true
360						break
361					}
362				}
363				pages = append(pages, p)
364			}
365		}
366		if len(skipped) > 0 {
367			logging.Debug(ctx, "semantic search: cells without query-serve skipped", "skipped_cells", skipped)
368		}
369		if len(pages) == 0 && lastErr == nil && len(skipped) > 0 {
370			lastErr = errNoRegionAvailable
371		}
372		return pages, failed, lastErr
373	}
374	
375	// errNoRegionAvailable is returned when every queried cell lacks query-serve.
376	var errNoRegionAvailable = errors.New("semantic search is not yet available in the region(s) hosting this search")
377	
378	// failedCell records one hard cell failure: its region label (operational
379	// metadata, safe to log) and a summarized, user-safe reason. The two are kept
380	// apart so the reason — which can contain response-body-derived content — stays
381	// out of the Debug log and only ever reaches the user-facing warning.
382	type failedCell struct {
383		label  string
384		reason string
385	}
386	
387	// maxCellErrorReason bounds the per-region reason shown in the partial-failure
388	// warning. A cell error can embed the raw response body — parseSearchResponse
389	// dumps string(body) on a decode failure or non-200 — so the reason is
390	// collapsed to a single line and truncated: enough to name the failure mode
391	// (e.g. "unexpected response from search service") without spilling a multi-MB
392	// body into the user's terminal.
393	const maxCellErrorReason = 200
394	
395	// summarizeCellError renders a cell's error as a short, single-line reason fit
396	// for the user-facing warning. A cell error can embed the raw, untrusted
397	// response body verbatim (parseSearchResponse dumps string(body) on a decode
398	// or non-200 failure), so this both bounds and sanitizes it: non-printable
399	// runes — ANSI escape / C0 / C1 / DEL bytes that could hijack the terminal
400	// when the reason is written to stderr — are replaced with spaces, then
401	// whitespace is collapsed and the result truncated on a rune boundary (never
402	// cutting a multibyte character in half). The body is treated as data, never
403	// as terminal control.
404	func summarizeCellError(err error) string {
405		if err == nil {
406			return "unknown error"
407		}
408		cleaned := strings.Map(func(r rune) rune {
409			if !unicode.IsPrint(r) {
410				return ' '
411			}
412			return r
413		}, err.Error())
414		reason := strings.Join(strings.Fields(cleaned), " ")
415		if reason == "" {
416			// An empty/whitespace-only (or all-control) error message would leave a
417			// dangling "label: " in the warning; fall back like the nil-error branch.
418			return "unknown error"
419		}
420		if runes := []rune(reason); len(runes) > maxCellErrorReason {
421			reason = string(runes[:maxCellErrorReason]) + "…"
422		}
423		return reason
424	}
425	
426	// rankSemanticResults buckets every page's rows and applies the ordering
427	// query-serve uses within a cell (and the BFF uses across cells): repos first,
428	// then tier-0 by BM25 desc, tier-1 by rerank score desc, promoted tier-2 by
429	// ANN asc. Tier-2 rows arriving alongside tier 0/1 from the same cell were
430	// deliberately promoted by query-serve; a cell whose page is entirely tier 2
431	// had nothing better — its ANN fallback, shown (uncapped here) only when tiers
432	// 0/1 are empty everywhere.
433	func rankSemanticResults(pages []semanticCellPage) (merged []search.Result, globalUpper bool) {
434		for _, p := range pages {
435			if p.hasUpper {
436				globalUpper = true
437				break
438			}
439		}
440	
441		var repos, tier0, tier1, promotedTier2, fallbackTier2 []search.Result
442		for _, p := range pages {
443			for _, r := range p.body.Results {
444				switch {
445				case r.Type == search.TypeRepo:
